const last={};let timer=null,busy=false,auditFlushed=0;
const rows=()=>{const r=[['meta',{seq:db.seq,tokens:db.tokens,vapid:db.vapid}],['settings',db.settings]];for(const k of['users','rides','tickets','leads','payments','alerts'])for(const id in db[k])r.push([k.slice(0,-1)+':'+id,db[k][id]]);for(let i=auditFlushed;i<db.audit.length;i++)r.push(['audit:'+String(i).padStart(10,'0'),db.audit[i]]);return r};
async function flush(){timer=null;if(!SBU)return fs.writeFile(DBF,JSON.stringify({...db}),()=>{});if(busy)return save();busy=true;
 try{const up=[],aN=db.audit.length;for(const[k,v]of rows()){const s=JSON.stringify(v);if(k.startsWith('audit:')||last[k]!==s)up.push([k,s])}let i=0;while(i<up.length){let n=0;const part=[];while(i<up.length&&(!part.length||n+up[i][1].length<1.5e6)){part.push(up[i]);n+=up[i][1].length;i++}
  const r=await fetch(SBU+'/rest/v1/kv',{method:'POST',headers:{...sbh,prefer:'resolution=merge-duplicates'},body:'['+part.map(([k,s])=>`{"k":${JSON.stringify(k)},"v":${s}}`).join(',')+']'});if(!r.ok)throw new Error(r.status+' '+await r.text());for(const[k,s]of part)if(!k.startsWith('audit:'))last[k]=s}auditFlushed=aN}
 catch(e){console.error('فشل الحفظ في Supabase:',e.message);setTimeout(save,5000)}busy=false}
const save=()=>{if(!timer)timer=setTimeout(flush,SBU?1500:300)};
